import React from "react";
import { useNavigate } from "react-router-dom";
import {
  FaJava,
  FaPython,
  FaDatabase,
  FaChartLine,
  FaLaptopCode
} from "react-icons/fa";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">
      <div className="container">

        {/* LEFT SIDE */}
        <div className="left">
          <p className="tag">WELCOME</p>

          <h1>
            I'm <span className="name">Swetha A</span>
          </h1>

          <h2 className="role">
            Full Stack Developer • System Builder • UI Thinker
          </h2>

          <p className="desc">
            I design structured systems and build meaningful applications
            where logic, design, and performance work together.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>
            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>
        </div>

        {/* RIGHT SIDE */}
        <div className="right">
          <div className="radar">

            <div className="glow"></div>

            <div className="ring r1"></div>
            <div className="ring r2"></div>
            <div className="ring r3"></div>

            <div className="sweep"></div>

            {/* CENTER */}
            <div className="center">
              <img
                src="https://cdn-icons-png.flaticon.com/512/1055/1055687.png"
                alt="girl working on laptop"
              />
            </div>

            {/* ORBITS (FIXED SYSTEM) */}
            <div className="orbit o1"><FaJava /></div>
            <div className="orbit o2"><FaPython /></div>
            <div className="orbit o3"><FaDatabase /></div>
            <div className="orbit o4"><FaChartLine /></div>
            <div className="orbit o5"><FaLaptopCode /></div>

          </div>
        </div>

      </div>

      <style>{`

      .hero {
        min-height: 100vh;
        display: flex;
        align-items: center;
        background: radial-gradient(circle at top, #0b1220, #050816);
        padding: 0 6%;
      }

      .container {
        display: grid;
        grid-template-columns: 1.3fr 1fr;
        gap: 40px;
        width: 100%;
        align-items: center;
      }

      /* LEFT */
      .tag {
        font-size: 12px;
        letter-spacing: 3px;
        color: #64748b;
      }

      h1 { font-size: 62px; }
      .name { color: #38BDF8; }

      .role {
        font-size: 20px;
        color: #94a3b8;
      }

      .desc {
        margin-top: 18px;
        font-size: 16px;
        color: #cbd5e1;
        line-height: 1.7;
        max-width: 520px;
      }

      .buttons {
        margin-top: 30px;
        display: flex;
        gap: 15px;
      }

      .btn {
        padding: 12px 22px;
        border-radius: 10px;
        font-weight: 600;
        border: 1px solid rgba(56,189,248,0.3);
        cursor: pointer;
      }

      .primary {
        background: #38BDF8;
        color: #0b1220;
      }

      .secondary {
        background: rgba(255,255,255,0.03);
        color: #38BDF8;
      }

      /* RADAR */
      .radar {
        position: relative;
        width: 420px;
        height: 420px;
        margin: auto;
        display: flex;
        align-items: center;
        justify-content: center;
      }

      .glow {
        position: absolute;
        width: 420px;
        height: 420px;
        background: radial-gradient(circle, rgba(56,189,248,0.18), transparent 70%);
        filter: blur(10px);
      }

      .ring {
        position: absolute;
        border-radius: 50%;
        border: 1px solid rgba(56,189,248,0.15);
      }

      .r1 { width: 380px; height: 380px; }
      .r2 { width: 280px; height: 280px; }
      .r3 { width: 180px; height: 180px; }

      /* SWEEP */
      .sweep {
        position: absolute;
        width: 200px;
        height: 200px;
        border-radius: 50%;
        background: conic-gradient(from 0deg, transparent, rgba(56,189,248,0.25), transparent);
        animation: rotate 4s linear infinite;
      }

      @keyframes rotate {
        100% { transform: rotate(360deg); }
      }

      /* CENTER */
      .center {
        position: absolute;
        z-index: 5;
      }

      .center img {
        width: 150px;
        filter: drop-shadow(0 0 18px rgba(56,189,248,0.5));
      }

      /* ORBITS (FIXED CLEAN SYSTEM) */
      .orbit {
        position: absolute;
        top: 50%;
        left: 50%;
        width: 55px;
        height: 55px;
        display: flex;
        align-items: center;
        justify-content: center;

        border-radius: 50%;
        background: rgba(255,255,255,0.08);
        border: 1px solid rgba(56,189,248,0.4);
        box-shadow: 0 0 18px rgba(56,189,248,0.35);

        transform-origin: 0 0;
        font-size: 24px;
        color: #38BDF8;
      }

      /* CLEAN ORBIT RADIUS SYSTEM (NO OVERLAP) */
      .o1 { animation: orbit 10s linear infinite; transform: rotate(0deg) translate(170px); }
      .o2 { animation: orbit 12s linear infinite; transform: rotate(72deg) translate(150px); }
      .o3 { animation: orbit 9s linear infinite; transform: rotate(144deg) translate(130px); }
      .o4 { animation: orbit 11s linear infinite; transform: rotate(216deg) translate(150px); }
      .o5 { animation: orbit 8s linear infinite; transform: rotate(288deg) translate(110px); }

      @keyframes orbit {
        from { transform: rotate(0deg) translate(var(--r, 150px)); }
        to   { transform: rotate(360deg) translate(var(--r, 150px)); }
      }

      /* PARTICLES REMOVED CLASH RISK (optional cleanup) */

      @media (max-width: 900px) {
        .container {
          grid-template-columns: 1fr;
          text-align: center;
        }

        h1 { font-size: 42px; }

        .buttons {
          justify-content: center;
        }

        .radar {
          margin-top: 40px;
        }
      }

      `}</style>

    </section>
  );
};

export default Hero;
